  sold_count INT NOT NULL DEFAULT 0,
  warranty_months INT NOT NULL DEFAULT 0,
  origin VARCHAR(255),
  `condition` VARCHAR(255),
  is_universal TINYINT(1) NOT NULL DEFAULT 0,
