  weight_kg DECIMAL(10,2),
  description TEXT,
  specs JSON,
  images JSON,
  created_at DATE,
  FOREIGN KEY (category_id) REFERENCES `catalog_categories`(id),
  FOREIGN KEY (brand_id) REFERENCES `catalog_brands`(id),
  KEY `idx_products_category` (category_id),
  KEY `idx_products_brand` (brand_id),
