UPDATE parts p JOIN catalog_products src ON src.sku=p.part_code SET p.unit='piece' WHERE BINARY p.unit=BINARY 'cái';

INSERT INTO part_categories (name, target_engine)
SELECT DISTINCT c.name, 'common' FROM catalog_categories c
WHERE NOT EXISTS (SELECT 1 FROM part_categories pc WHERE pc.name = c.name);

INSERT INTO parts (category_id, part_code, name, unit, import_price, selling_price,
                   stock_quantity, min_stock_alert, is_active)
SELECT pc.id, p.sku, p.name, 'piece', 0, COALESCE(p.sale_price, p.price), p.stock, 0, 1
FROM catalog_products p
JOIN catalog_categories c ON c.id = p.category_id
JOIN part_categories pc ON pc.name = c.name
WHERE NOT EXISTS (SELECT 1 FROM parts existing WHERE existing.part_code = p.sku);

COMMIT;
SET SESSION sql_mode = @SYNC_OLD_SQL_MODE;

SELECT 'catalog_vehicle_makes' AS table_name, COUNT(*) AS row_count FROM catalog_vehicle_makes
UNION ALL SELECT 'catalog_brands', COUNT(*) FROM catalog_brands
UNION ALL SELECT 'catalog_categories', COUNT(*) FROM catalog_categories
UNION ALL SELECT 'catalog_vehicles', COUNT(*) FROM catalog_vehicles
UNION ALL SELECT 'catalog_products', COUNT(*) FROM catalog_products
UNION ALL SELECT 'catalog_product_vehicle_compatibility', COUNT(*) FROM catalog_product_vehicle_compatibility;
SELECT COUNT(*) AS linked_products FROM catalog_products p JOIN parts x ON x.part_code = p.sku;
SELECT COUNT(*) AS missing_parts FROM catalog_products p LEFT JOIN parts x ON x.part_code = p.sku WHERE x.id IS NULL;
